-- Phase 6 adds authority and communication without rewriting commercial history.
CREATE TABLE consumer_mandates(id TEXT PRIMARY KEY, group_id TEXT NOT NULL, user_id TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','PAUSED','REVOKED')), replan INTEGER NOT NULL CHECK(replan IN (0,1)), better_offers INTEGER NOT NULL CHECK(better_offers IN (0,1)), boundary_fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(group_id,user_id,version), FOREIGN KEY(group_id,user_id) REFERENCES group_members(group_id,user_id));
CREATE TABLE merchant_agent_policies(id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL REFERENCES merchants(id), version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('ACTIVE','PAUSED','REVOKED')), terms_json TEXT NOT NULL CHECK(json_valid(terms_json)), confirmed_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(merchant_id,version));
CREATE TABLE group_agent_settings(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id), version INTEGER NOT NULL, auto_finalize INTEGER NOT NULL CHECK(auto_finalize IN (0,1)), confirmed_by TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(group_id,version));
CREATE TABLE saga_delegations(saga_id TEXT PRIMARY KEY REFERENCES capture_sagas(id),authority_id TEXT NOT NULL REFERENCES group_agent_settings(id));
CREATE TRIGGER immutable_saga_delegation BEFORE UPDATE ON saga_delegations BEGIN SELECT RAISE(ABORT,'AUTHORITY_IMMUTABLE'); END;
CREATE TABLE domain_events(id TEXT PRIMARY KEY, type TEXT NOT NULL, aggregate_id TEXT NOT NULL, revision INTEGER, dedupe_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','PROCESSING','PROCESSED','FAILED')), attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, lease_owner TEXT, lease_until TEXT, created_at TEXT NOT NULL, processed_at TEXT, error_code TEXT);
CREATE INDEX event_work ON domain_events(state,available_at);
CREATE TABLE agent_watch_state(id TEXT PRIMARY KEY,source_hash TEXT NOT NULL,version INTEGER NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE merchant_demand_projection(cohort_id TEXT PRIMARY KEY,data_json TEXT NOT NULL CHECK(json_valid(data_json)),curve_json TEXT NOT NULL CHECK(json_valid(curve_json)),updated_at TEXT NOT NULL);
CREATE TABLE group_projection_bindings(group_id TEXT PRIMARY KEY REFERENCES groups(id),cohort_id TEXT NOT NULL UNIQUE REFERENCES merchant_demand_projection(cohort_id));
CREATE TABLE activity_events(id TEXT PRIMARY KEY, recipient_kind TEXT NOT NULL CHECK(recipient_kind IN ('CONSUMER','MERCHANT')), recipient_id TEXT NOT NULL, group_id TEXT, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, deep_link TEXT NOT NULL, actionable INTEGER NOT NULL CHECK(actionable IN (0,1)), dedupe_key TEXT NOT NULL UNIQUE, read_at TEXT, resolved_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX activity_recipient ON activity_events(recipient_kind,recipient_id,group_id,created_at);
CREATE TABLE agent_activity(id TEXT PRIMARY KEY, audience TEXT NOT NULL CHECK(audience IN ('CONSUMER','MERCHANT')), group_id TEXT, merchant_id TEXT, event_id TEXT NOT NULL REFERENCES domain_events(id), authority_id TEXT, authority_version INTEGER, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(event_id,audience,group_id,title));
CREATE TABLE policy_publications(policy_id TEXT NOT NULL REFERENCES merchant_agent_policies(id), demand_hash TEXT NOT NULL, offer_id TEXT NOT NULL UNIQUE REFERENCES merchant_offer_versions(id), simulation_id TEXT NOT NULL REFERENCES merchant_offer_simulations(id), event_id TEXT NOT NULL REFERENCES domain_events(id), created_at TEXT NOT NULL, demand_snapshot_json TEXT NOT NULL CHECK(json_valid(demand_snapshot_json)), PRIMARY KEY(policy_id,demand_hash));
CREATE TABLE notification_preferences(group_id TEXT NOT NULL, user_id TEXT NOT NULL, push_enabled INTEGER NOT NULL DEFAULT 0 CHECK(push_enabled IN (0,1)), progress INTEGER NOT NULL DEFAULT 0 CHECK(progress IN (0,1)), recommendations INTEGER NOT NULL DEFAULT 1 CHECK(recommendations IN (0,1)), PRIMARY KEY(group_id,user_id), FOREIGN KEY(group_id,user_id) REFERENCES group_members(group_id,user_id));
CREATE TABLE push_subscriptions(id TEXT PRIMARY KEY, group_id TEXT NOT NULL, user_id TEXT NOT NULL, endpoint_hash TEXT NOT NULL UNIQUE, subscription_json TEXT NOT NULL CHECK(json_valid(subscription_json)), expires_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(group_id,user_id) REFERENCES group_members(group_id,user_id));
CREATE TABLE notification_outbox(id TEXT PRIMARY KEY, activity_id TEXT NOT NULL REFERENCES activity_events(id), subscription_id TEXT NOT NULL REFERENCES push_subscriptions(id) ON DELETE CASCADE, state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','SENT','FAILED')), attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, UNIQUE(activity_id,subscription_id));
CREATE TABLE group_invites(token_hash TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id), expires_at TEXT NOT NULL, max_members INTEGER NOT NULL CHECK(max_members BETWEEN 2 AND 6), revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE joined_identities(session_id TEXT PRIMARY KEY REFERENCES demo_sessions(id), user_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE agent_worker_sessions(group_id TEXT PRIMARY KEY REFERENCES groups(id),session_id TEXT NOT NULL UNIQUE REFERENCES demo_sessions(id));
CREATE TRIGGER immutable_consumer_mandate BEFORE UPDATE ON consumer_mandates BEGIN SELECT RAISE(ABORT,'AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER immutable_merchant_policy BEFORE UPDATE ON merchant_agent_policies BEGIN SELECT RAISE(ABORT,'AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER immutable_group_authority BEFORE UPDATE ON group_agent_settings BEGIN SELECT RAISE(ABORT,'AUTHORITY_IMMUTABLE'); END;
CREATE TRIGGER immutable_policy_receipt BEFORE UPDATE ON policy_publications BEGIN SELECT RAISE(ABORT,'AUTHORITY_IMMUTABLE'); END;
CREATE UNIQUE INDEX agent_audit_dedupe ON agent_activity(event_id,audience,IFNULL(group_id,''),IFNULL(authority_id,''),title);
